# SPDX-License-Identifier: MIT
# Trusted setup control for halt/poweroff/reboot fixtures (pane 214). Run
# under the same system-seccomp.py rules (or namespace construction) as the
# behavior, it makes the filtered calls itself so a broken mechanism is a
# setup ERROR before any candidate behavior. Every reboot(2) it issues is
# preceded by a CapEff == 0 check, or uses an invalid magic, or runs inside a
# private PID namespace, so it can never restart the guest.
# Usage:
#   power_control.py call sync|syncfs|badmagic|quiet   (kill-rule probes; exit 0 if not killed)
#   power_control.py expect CMD WANT     sync, then reboot(MAGIC1, MAGIC2, CMD); WANT ok or errno name
#   power_control.py log LOG CALLS       recorded sync/syncfs/reboot sequence must equal CALLS
#   power_control.py refusal             real reboot(2) with an invalid magic must give EPERM
#   power_control.py pidns CMD           real reboot(MAGIC1, MAGIC2, CMD) as PID 1 of a private PID namespace
import ctypes, errno, json, os, pathlib, sys

lib = ctypes.CDLL(None, use_errno=True)
L = ctypes.c_long
SYS_REBOOT = 169
MAGIC1, MAGIC2 = 0xfee1dead, 0x28121969


def cap_eff():
    for line in pathlib.Path('/proc/self/status').read_text().splitlines():
        if line.startswith('CapEff:'):
            return int(line.split()[1], 16)
    raise AssertionError('no CapEff')


def reboot(magic1, cmd):
    ctypes.set_errno(0)
    rc = lib.syscall(L(SYS_REBOOT), L(magic1), L(MAGIC2), L(cmd), L(0))
    return rc, ctypes.get_errno()


def fail(message):
    print('CONTROL-FAILED ' + message)
    sys.exit(98)


def main():
    command = sys.argv[1]
    if command == 'call':
        kind = sys.argv[2]
        if kind == 'sync':
            os.sync()
        elif kind == 'syncfs':
            fd = os.open('.', os.O_RDONLY)
            lib.syncfs(fd)
            os.close(fd)
        elif kind == 'badmagic':
            reboot(0x1, 0)
        elif kind != 'quiet':
            raise AssertionError(kind)
        print('not killed: %s' % kind)
    elif command == 'expect':
        cmd, want = int(sys.argv[2], 16), sys.argv[3]
        if cap_eff() != 0:
            print('SETUP-INVALID CapEff is not empty; refusing to issue reboot(2)')
            sys.exit(97)
        os.sync()
        rc, code = reboot(MAGIC1, cmd)
        if (want == 'ok' and rc != 0) or (want != 'ok' and (rc != -1 or code != getattr(errno, want))):
            fail('reboot returned %d errno %d, wanted %s' % (rc, code, want))
        print('mechanism control ok')
    elif command == 'log':
        path, want = pathlib.Path(sys.argv[2]), sys.argv[3]
        calls = []
        for line in (path.read_text().splitlines() if path.exists() else []):
            record = json.loads(line)
            if record['syscall'] in ('sync', 'syncfs'):
                calls.append(record['syscall'])
            elif record['syscall'] == 'reboot':
                calls.append('reboot(%08x,%08x,%08x)' % (record['arg0'], record['arg1'], record['arg2']))
        if ','.join(calls) != want:
            fail('recorded %s, wanted %s' % (','.join(calls), want))
        if path.exists():
            path.unlink()
        print('notification control ok')
    elif command == 'refusal':
        if cap_eff() != 0:
            print('SETUP-INVALID CapEff is not empty')
            sys.exit(97)
        rc, code = reboot(0x1, 0)
        if rc != -1 or code != errno.EPERM:
            fail('unprivileged reboot(2) gave %d errno %d, wanted EPERM' % (rc, code))
        print('refusal control ok')
    elif command == 'pidns':
        if os.getpid() != 1:
            print('SETUP-INVALID not PID 1 of a private PID namespace')
            sys.exit(97)
        reboot(MAGIC1, int(sys.argv[2], 16))
        sys.exit(90 + ctypes.get_errno())
    else:
        raise AssertionError(command)


if __name__ == '__main__':
    main()

