            elif record['syscall'] == 'reboot':
                calls.append('reboot(%08x,%08x,%08x)' % (record['arg0'], record['arg1'], record['arg2']))
        if ','.join(calls) != want:
            fail('recorded %s, wanted %s' % (','.join(calls), want))
        if path.exists():
            path.unlink()
        print('notification control ok')
    elif command == 'refusal':
        if cap_eff() != 0:
            print('SETUP-INVALID CapEff is not empty')
            sys.exit(97)
        rc, code = reboot(0x1, 0)
        if rc != -1 or code != errno.EPERM:
            fail('unprivileged reboot(2) gave %d errno %d, wanted EPERM' % (rc, code))
        print('refusal control ok')
    elif command == 'pidns':
        if os.getpid() != 1:
            print('SETUP-INVALID not PID 1 of a private PID namespace')
            sys.exit(97)
        reboot(MAGIC1, int(sys.argv[2], 16))
        sys.exit(90 + ctypes.get_errno())
    else:
        raise AssertionError(command)


